use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;
const NO_KNOWLEDGE: &str = "No relevant knowledge base entries were found for this question.";

struct Node;

/// Bound a string to at most `max` characters (Unicode scalar values),
/// matching Python's `len` on `str`.
fn bound_chars(s: String, max: usize) -> String {
    if s.chars().count() <= max {
        s
    } else {
        s.chars().take(max).collect()
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let CustomerQuery {
            intent, question, ..
        } = query.query;

        // The contract's `requires` already bounds the question; bounding again
        // keeps the `ensures` true regardless of the input.
        let question = bound_chars(question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

